---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Form: A project brief with inline checks and an agent that drafts the rest.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change form.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './form.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="form" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<form class="fmx panel" novalidate>
  <div class="fmx-h"><b>New project brief</b><button type="button" class="pill soft sm fmx-ai"><svg class="i xs"><use href="#i-spark"/></svg>Draft with agent</button></div>
  <label class="fmx-f"><span>Project name<i class="fmx-dr" aria-hidden="true"><svg class="i xs"><use href="#i-spark"/></svg>Drafted</i></span><input name="n" placeholder="Pricing refresh" maxlength="40"><em class="fmx-c num">0/40</em></label>
  <label class="fmx-f"><span>Goal<i class="fmx-dr" aria-hidden="true"><svg class="i xs"><use href="#i-spark"/></svg>Drafted</i></span><textarea name="g" rows="2" placeholder="What should change, and why?"></textarea></label>
  <div class="fmx-f"><span>Type</span><div class="fmx-ty"><button type="button" class="chip sm" data-v="web">Website</button><button type="button" class="chip sm" data-v="app">App</button><button type="button" class="chip sm" data-v="brand">Brand</button></div></div>
  <label class="fmx-f"><span>Due<i class="fmx-dr" aria-hidden="true"><svg class="i xs"><use href="#i-spark"/></svg>Drafted</i></span><input name="d" type="text" placeholder="Nov 14"></label>
  <div class="fmx-ft"><span class="fmx-ms muted"></span><button class="pill primary sm fmx-go" type="submit">Create brief</button></div>
</form>
  </Fragment></div>
</div>
<script>
  import './form.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Form ---------- */
.fmx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3);max-width:380px;margin:0 auto;width:100%}
.fmx-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2)}
.fmx-h b{font-weight:500;font-size:14px}
.fmx-f{display:flex;flex-direction:column;gap:5px;font-size:12.5px;font-weight:500;position:relative}
.fmx-f input,.fmx-f textarea{border:0;outline:0;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);padding:10px var(--dm-s-3);font:inherit;font-size:13.5px;line-height:20px;font-weight:400;color:var(--dm-fg);resize:none;transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.fmx-f :is(input,textarea){corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.fmx-f input::placeholder,.fmx-f textarea::placeholder{color:var(--dm-muted)}
.fmx-f input:focus,.fmx-f textarea:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* a field marked wrong keeps its red edge, focused or not, until it is fixed; the message says what is wrong */
.fmx-f.bad input,.fmx-f.bad textarea{box-shadow:inset 0 0 0 1px var(--dm-bad)}
.fmx-f .er{font-size:11.5px;color:var(--dm-bad);font-weight:400;animation:enter .35s var(--dm-ease) backwards}
/* what the agent drafted says so quietly at the end of its label's line, every mark on the content's right edge, until
   someone edits it */
.fmx-f>span:first-child{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2)}
.fmx-dr{display:inline-flex;align-items:center;gap:3px;font-style:normal;font-size:11px;font-weight:400;color:var(--dm-muted);opacity:0;transform:translateX(-3px);transition:opacity var(--dm-t) var(--dm-ease),transform var(--dm-t) var(--dm-ease)}
.fmx-dr .i{color:var(--dm-accent-fg,var(--dm-accent))}
.fmx-f.ai .fmx-dr{opacity:1;transform:none}
.fmx-c{position:absolute;right:12px;top:24px;height:40px;display:flex;align-items:center;font-style:normal;font-size:11px;color:var(--dm-muted);font-weight:400;pointer-events:none}
.fmx-ty{display:flex;gap:6px}
/* the types are white chips with a dimmed grey edge; the picked one's edge is a step stronger. A hover is a quiet fill */
.fmx-ty .chip{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent)}
@media (hover:hover) and (pointer:fine){.fmx-ty .chip:hover{background:color-mix(in srgb,var(--dm-fg) 4%,var(--dm-surface))}}
.fmx-ty .chip.on{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-on) 50%,transparent)}
/* the footer sits under a hairline in Soft and Blueprint (owner, 21 Nov), 16px under the fields and 12px over its button */
.fmx-ft{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2);margin-top:var(--dm-s-1);padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
/* Clean: the footer is the card's off-white foot strip (owner, 21 Nov: "clean doesnt follow its style with buttons being
   separated by a divider line and on a gray bg"): its words and Create brief 16px in, 16px from the strip's top and bottom (owner, 23 Nov) */
:root[data-style="clean"] .fmx-ft,:root [data-style="clean"] .fmx-ft,:root [data-style="clean"].fmx-ft{padding-top:0;border-top:0}
:root[data-style="clean"] .fmx.panel .fmx-ft,:root [data-style="clean"] .fmx.panel .fmx-ft,:root [data-style="clean"].fmx.panel .fmx-ft{margin:var(--dm-s-1) -16px -16px;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
.fmx-ms{font-size:12px}
/* nothing in it grows or shrinks when pressed but Clean's ink primary; a button whose words change eases to their width */
.fmx :is(.pill,.chip):active{transform:none}
.fmx :is(.fmx-ai,.fmx-go){overflow:hidden}
.fmx-ai .shim{font-size:inherit}
/* the green tick on the button's grey fill keeps 3:1 (the vivid green with a touch of the text green) */
.fmx-ai.done .i{color:color-mix(in srgb,var(--dm-ok-mark) 70%,var(--dm-ok))}
/* the words on a filled button sweep in its own text colour */
.fmx-go .shim{background-image:linear-gradient(90deg,var(--dm-on-accent) 0%,var(--dm-on-accent) 38%,color-mix(in srgb,var(--dm-on-accent) 45%,transparent) 50%,var(--dm-on-accent) 62%,var(--dm-on-accent) 100%);font-size:inherit}
:root[data-style="clean"] .fmx-go .shim,:root [data-style="clean"] .fmx-go .shim,:root [data-style="clean"].fmx-go .shim{background-image:linear-gradient(90deg,var(--dm-on-btn) 0%,var(--dm-on-btn) 38%,color-mix(in srgb,var(--dm-on-btn) 45%,transparent) 50%,var(--dm-on-btn) 62%,var(--dm-on-btn) 100%)}
/* the type chips keep their quiet edge: the one hover fills them, and a picked one has the stronger fill (owner, 21 Nov) */
:root[data-style="clean"] .fmx-ty .chip,:root [data-style="clean"] .fmx-ty .chip,:root [data-style="clean"].fmx-ty .chip{transition:background-color var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .fmx-ty .chip:not(.on):hover,:root [data-style="clean"] .fmx-ty .chip:not(.on):hover,:root [data-style="clean"].fmx-ty .chip:not(.on):hover{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent),inset 0 0 0 99px var(--dm-row)}}
:root[data-style="clean"] .fmx-ty .chip.on,:root [data-style="clean"] .fmx-ty .chip.on,:root [data-style="clean"].fmx-ty .chip.on{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent),inset 0 0 0 99px var(--dm-row-on)}
/* done: the card eases to the confirmation's height (grow()), with the vivid green tick */
.fmx-done{display:flex;flex-direction:column;align-items:center;gap:6px;padding:var(--dm-s-6) 0;text-align:center;font-size:13px}
.fmx-done>svg.i{width:28px;height:28px;color:var(--dm-ok-mark)}
.fmx-done>b{font-weight:500;font-size:14px}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, grow, html, stagger, swap } from '../core/core.js';
DM.def('form', (r, c) => {
  r.innerHTML = r.innerHTML.split('{spark}').join(I('spark','xs'));
  const form = $('.fmx', r), n = $('[name=n]', r), g = $('[name=g]', r), d = $('[name=d]', r), cnt = $('.fmx-c', r), ms = $('.fmx-ms', r);
  // the card grows with its messages and eases to the confirmation's height, keeping no room for either
  c.offs.push(grow(form));
  // a button whose words change eases to their width, with no room kept for the longer ones
  const label = (b, h) => { const w0 = b.offsetWidth; b.innerHTML = h; const w1 = b.offsetWidth, cs = getComputedStyle(form);
    if (!REDUCE && w0 && Math.abs(w1 - w0) > .5) b.animate([{ width:w0 + 'px' }, { width:w1 + 'px' }], { duration:(parseFloat(cs.getPropertyValue('--dm-t')) || .34) * 1000, easing:cs.getPropertyValue('--dm-ease').trim() || 'ease' }); };
  let type = null;
  n.oninput = () => { cnt.textContent = n.value.length + '/40'; clear(n); };
  g.oninput = () => clear(g); d.oninput = () => clear(d);
  const chips = $$('.fmx-ty .chip', r);
  chips.forEach(ch => ch.onclick = () => { type = ch.dataset.v; chips.forEach(x => x.classList.toggle('on', x === ch)); clear(ch.parentElement); });
  function clear(el){ const f = el.closest('.fmx-f'); f.classList.remove('bad', 'ai'); $('.er', f)?.remove(); }
  function bad(el, t){ const f = el.closest('.fmx-f'); if (f.classList.contains('bad')) return; f.classList.add('bad'); f.insertAdjacentHTML('beforeend', `<span class="er">${t}</span>`); }
  async function type_(el, s){ el.closest('.fmx-f').classList.add('ai'); el.value = ''; for (const ch of s){ el.value += ch; el.dispatchEvent(new Event('input')); el.closest('.fmx-f').classList.add('ai'); await c.wait(18); } }
  // the agent's draft: the button says Drafting with the highlight sweep while it types, then Drafted with the green tick
  let drafting = false;
  $('.fmx-ai', r).onclick = () => { if (drafting) return; drafting = true; c.run(async () => {
    const b = $('.fmx-ai', r); label(b, '<span class="think on"><i></i><i></i><i></i><i></i></span><span class="shim">Drafting</span>');
    if (!n.value) await type_(n, 'Pricing refresh');
    await type_(g, 'Lift trial to paid by showing annual plans first and keeping one CTA per card.');
    if (!type) chips[0].click();
    if (!d.value) await type_(d, 'Nov 14');
    label(b, I('check','xs') + 'Drafted'); b.classList.add('done'); swap(ms, 'Review what the agent drafted'); drafting = false;
  }); };
  // the preview has the agent fill it in once on its own, unless you take over first. The agent's typing keeps going under the
  // pointer (DM.PLAYS); the press that starts it waits while a mouse rests on the card
  c.auto(1400, function go(){ if (c.mine) return; if (r.matches(':hover')) return c.later(250, go); if (!n.value) $('.fmx-ai', r).click(); });
  let sent = false;
  form.onsubmit = e => { e.preventDefault(); let ok = true;
    if (!n.value.trim()){ bad(n, 'Give it a name'); ok = false; }
    if (g.value.trim().length < 12){ bad(g, 'Add a sentence about the goal'); ok = false; }
    if (!type){ bad(chips[0], 'Pick a type'); ok = false; }
    if (!ok) return swap(ms, 'A few fields need a look');
    if (sent) return; sent = true;
    c.run(async () => { const go = $('.fmx-go', r); label(go, '<span class="spin"></span><span class="shim">Creating</span>'); await c.wait(800);
      // the fields give way to the confirmation, and the card eases to its height
      const into = $(':scope>.dm-grow', form) || form;
      [...into.children].forEach(k => k.hidden = true); const dn = html(`<div class="fmx-done" role="status">${I('ok')}<b>${n.value} created</b><span class="muted">The agent is gathering references now</span></div>`); into.appendChild(dn); stagger([...dn.children], 70); }); };
});
